"use client";
/* eslint-disable react-hooks/set-state-in-effect */

import { tenantDateTimeFormatter } from "@/lib/client-timezone";
import type { CSSProperties, FormEvent, ReactNode } from "react";
import { useCallback, useEffect, useState } from "react";
import Link from "next/link";
import { ErpIcon } from "@/components/erp/erp-icon";
import { ErpModal } from "@/components/erp/modal-portal";
import styles from "./privacy-governance-center.module.css";

type EventItem = { id: number; kind: string; fromStatus: string | null; toStatus: string | null; note: string | null; actorId: string; actorName: string; createdAt: string };
type RequestItem = { id: number; number: string; type: string; subjectName: string; subjectDocument: string; contact: string; status: string; priority: string; channel: string; requesterRelation: string; identityMethod: string | null; dueAt: string; verifiedAt: string | null; completedAt: string | null; evidence: string | null; responseSummary: string | null; rejectionReason: string | null; assignedTo: string | null; createdBy: string; version: number; createdAt: string; updatedAt: string; events?: EventItem[] };
type LegalBasis = { id: number; name: string; basis: string; purpose: string; dataCategory: string; description: string | null; dataSubjects: unknown; sourceSystems: unknown; recipients: unknown; internationalTransfer: boolean; safeguards: string | null; owner: string | null; reviewAt: string | null; active: boolean; version: number };
type Retention = { id: number; dataCategory: string; retentionDays: number; legalReason: string; action: string; appliesTo: string | null; owner: string | null; reviewAt: string | null; active: boolean; version: number };
type Incident = { id: number; title: string; severity: string; description: string; status: string; affectedSubjects: number; riskRelevant: boolean; dataCategories: unknown; detectedAt: string; notificationDueAt: string | null; containedAt: string | null; anpdNotifiedAt: string | null; subjectsNotifiedAt: string | null; rootCause: string | null; containmentMeasures: string | null; correctiveActions: string | null; decisionReason: string | null; assignedTo: string | null; reportedAt: string; resolvedAt: string | null; version: number; events: EventItem[] };
type Treatment = { id: string; name: string; department: string; purpose: string; legalBasis: string; dataCategories: unknown; dataSubjects: unknown; operations: unknown; collectionSource: string | null; recipients: unknown; systems: unknown; sensitiveData: boolean; childrenData: boolean; internationalTransfer: boolean; transferSafeguards: string | null; securityMeasures: string | null; retentionSummary: string | null; owner: string; riskLevel: string; status: string; lastReviewedAt: string | null; nextReviewAt: string | null; version: number; _count: { assessments: number } };
type Assessment = { id: string; treatmentId: string | null; title: string; reason: string; status: string; inherentRisk: string; residualRisk: string; risks: unknown; safeguards: unknown; necessity: string | null; proportionality: string | null; dpoOpinion: string | null; approvedBy: string | null; approvedAt: string | null; reviewAt: string | null; version: number; treatment: { id: string; name: string; department: string } | null };
type Filters = { search: string; status: string; type: string; priority: string; sort: "newest" | "oldest" };
type Data = {
  requests: RequestItem[]; pagination: { page: number; limit: number; total: number; pages: number }; bases: LegalBasis[]; retention: Retention[]; incidents: Incident[]; treatments: Treatment[]; assessments: Assessment[];
  actors: Array<{ id: string; name: string; email: string }>;
  settings: { dataProtectionOfficerName: string | null; dataProtectionEmail: string | null; dataProtectionPhone: string | null; privacySmallAgent: boolean; privacyDefaultRequestDays: number; privacyProgramReviewAt: string | null; timezone: string };
  summary: { openRequests: number; overdueRequests: number; dueSoon: number; urgentRequests: number; completed30: number; averageResolutionDays: number; openIncidents: number; notificationAtRisk: number; mappedTreatments: number; highRiskTreatments: number; assessmentsPending: number; consentRecords: Record<string, number>; readiness: { score: number; checks: Array<{ key: string; label: string; ok: boolean }> } };
  trend: Array<{ date: string; requests: number; incidents: number }>; capabilities: { canWrite: boolean; canExport: boolean }; generatedAt: string;
};
type Modal = { kind: "request" | "basis" | "retention" | "incident" | "treatment" | "assessment" | "settings"; item?: LegalBasis | Retention | Treatment | Assessment };
type Tab = "overview" | "requests" | "inventory" | "policies" | "incidents" | "impact";

const EMPTY_FILTERS: Filters = { search: "", status: "", type: "", priority: "", sort: "newest" };
const date = tenantDateTimeFormatter({ dateStyle: "short" }), dateTime = tenantDateTimeFormatter({ dateStyle: "short", timeStyle: "short" }), compact = tenantDateTimeFormatter({ day: "2-digit", month: "short" });

export function PrivacyGovernanceCenter() {
  const [data, setData] = useState<Data | null>(null), [loading, setLoading] = useState(true), [error, setError] = useState(""), [notice, setNotice] = useState(""), [tab, setTab] = useState<Tab>("overview"), [filters, setFilters] = useState(EMPTY_FILTERS), [activeFilters, setActiveFilters] = useState(EMPTY_FILTERS), [page, setPage] = useState(1), [busy, setBusy] = useState(false), [modal, setModal] = useState<Modal | null>(null), [requestDetail, setRequestDetail] = useState<RequestItem | null>(null), [incidentDetail, setIncidentDetail] = useState<Incident | null>(null);
  const load = useCallback(async () => {
    setLoading(true); setError("");
    try { const params = filterParams(activeFilters); params.set("page", String(page)); params.set("limit", "50"); const response = await fetch(`/api/erp/privacy?${params}`, { cache: "no-store" }), body = await response.json(); if (!response.ok) throw new Error(body.error || "Não foi possível carregar a central de privacidade."); setData(body); setRequestDetail((current) => current ? body.requests.find((item: RequestItem) => item.id === current.id) || current : null); setIncidentDetail((current) => current ? body.incidents.find((item: Incident) => item.id === current.id) || current : null); }
    catch (reason) { setError(reason instanceof Error ? reason.message : "Não foi possível carregar a central de privacidade."); }
    finally { setLoading(false); }
  }, [activeFilters, page]);
  useEffect(() => { void load(); }, [load]);
  async function command(payload: Record<string, unknown>) { setBusy(true); setError(""); try { const response = await fetch("/api/erp/privacy", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(payload) }), body = await response.json(); if (!response.ok) throw new Error(body.error || "Não foi possível concluir a operação."); return body as Record<string, unknown>; } catch (reason) { setError(reason instanceof Error ? reason.message : "Não foi possível concluir a operação."); return null; } finally { setBusy(false); } }
  async function submit(action: string, payload: Record<string, unknown>) { const result = await command({ action, ...payload }); if (!result) return; setModal(null); setNotice("Alteração registrada com histórico e correlação de auditoria."); await load(); }
  async function exportCsv() { if (!data) return; const result = await command({ action: "export.record", filters: activeFilters, estimatedRows: data.pagination.total }); if (!result) return; const params = filterParams(activeFilters); params.set("format", "csv"); params.set("exportId", String(result.exportId)); const anchor = document.createElement("a"); anchor.href = `/api/erp/privacy?${params}`; anchor.download = ""; anchor.click(); setNotice("Exportação registrada e iniciada."); }
  function apply(event: FormEvent) { event.preventDefault(); setActiveFilters(filters); setPage(1); setTab("requests"); }
  if (!data && loading) return <Loading />;
  if (!data) return <Fatal message={error} retry={() => void load()} />;
  const urgent = data.summary.overdueRequests + data.summary.notificationAtRisk, maxTrend = Math.max(1, ...data.trend.map((item) => item.requests + item.incidents));
  return <div className={styles.workspace}>
    <section className={styles.hero}>
      <div><span>PRIVACIDADE POR DESIGN · LGPD</span><h1>Central de privacidade</h1><p>Controle direitos dos titulares, inventário de tratamentos, hipóteses legais, retenção, RIPD e resposta a incidentes em uma única trilha de prestação de contas.</p><nav aria-label="Atalhos de privacidade"><Link href="/erp/clientes"><ErpIcon name="customers" />Titulares</Link><Link href="/erp/atividades-auditoria"><ErpIcon name="activities" />Auditoria</Link><Link href="/erp/biblioteca"><ErpIcon name="library" />Evidências</Link></nav></div>
      <section aria-label="Prontidão do programa"><div className={styles.scoreRing} style={{ "--score": `${data.summary.readiness.score * 3.6}deg` } as CSSProperties}><b>{data.summary.readiness.score}%</b><small>prontidão</small></div><span><strong>{urgent ? `${urgent} ponto${urgent === 1 ? "" : "s"} exige${urgent === 1 ? "" : "m"} ação` : "Operação sem prazo crítico"}</strong><small>{data.settings.dataProtectionOfficerName ? `${data.settings.dataProtectionOfficerName} · ${data.settings.dataProtectionEmail || "canal incompleto"}` : "Defina o encarregado e seu canal público"}</small></span></section>
    </section>
    <section className={styles.metrics} aria-label="Indicadores de privacidade"><Metric label="Solicitações abertas" value={data.summary.openRequests} detail={`${data.summary.overdueRequests} vencidas · ${data.summary.dueSoon} próximas`} tone={data.summary.overdueRequests ? "danger" : "good"} /><Metric label="Concluídas em 30 dias" value={data.summary.completed30} detail={`Tempo médio: ${data.summary.averageResolutionDays} dias`} /><Metric label="Tratamentos mapeados" value={data.summary.mappedTreatments} detail={`${data.summary.highRiskTreatments} de maior risco`} /><Metric label="RIPDs em andamento" value={data.summary.assessmentsPending} detail={`${data.assessments.filter((item) => item.status === "approved").length} aprovados`} /><Metric label="Incidentes abertos" value={data.summary.openIncidents} detail={`${data.summary.notificationAtRisk} com comunicação crítica`} tone={data.summary.notificationAtRisk ? "danger" : data.summary.openIncidents ? "warning" : "good"} /><Metric label="Manifestações" value={Object.values(data.summary.consentRecords).reduce((sum, value) => sum + value, 0)} detail={`${data.summary.consentRecords.granted || 0} consentimentos concedidos`} /></section>
    <section className={styles.navbar}><div role="tablist" aria-label="Áreas da central">{([['overview','Visão geral'],['requests','Titulares'],['inventory','Inventário'],['policies','Bases e retenção'],['incidents','Incidentes'],['impact','RIPD e governança']] as Array<[Tab,string]>).map(([key, label]) => <button type="button" role="tab" aria-selected={tab === key} key={key} onClick={() => setTab(key)}>{label}{key === "requests" && <b>{data.summary.openRequests}</b>}{key === "incidents" && data.summary.openIncidents > 0 && <b>{data.summary.openIncidents}</b>}</button>)}</div><div><button type="button" onClick={() => void load()} disabled={loading}>↻ Atualizar</button>{data.capabilities.canWrite && <button type="button" className={styles.primary} onClick={() => setModal({ kind: "request" })}>＋ Nova solicitação</button>}</div></section>
    {(error || notice) && <div className={error ? styles.error : styles.notice} role={error ? "alert" : "status"}><span>{error || notice}</span><button type="button" onClick={() => { setError(""); setNotice(""); }}>×</button></div>}
    {tab === "overview" && <Overview data={data} maxTrend={maxTrend} openRequest={setRequestDetail} openIncident={setIncidentDetail} configure={() => setModal({ kind: "settings" })} navigate={setTab} />}
    {tab === "requests" && <Requests data={data} filters={filters} setFilters={setFilters} apply={apply} reset={() => { setFilters(EMPTY_FILTERS); setActiveFilters(EMPTY_FILTERS); setPage(1); }} page={page} setPage={setPage} open={setRequestDetail} create={() => setModal({ kind: "request" })} exportCsv={exportCsv} />}
    {tab === "inventory" && <Inventory data={data} edit={(item) => setModal({ kind: "treatment", item })} create={() => setModal({ kind: "treatment" })} createImpact={(item) => setModal({ kind: "assessment", item: { treatmentId: item.id } as Assessment })} />}
    {tab === "policies" && <Policies data={data} editBasis={(item) => setModal({ kind: "basis", item })} editRetention={(item) => setModal({ kind: "retention", item })} createBasis={() => setModal({ kind: "basis" })} createRetention={() => setModal({ kind: "retention" })} />}
    {tab === "incidents" && <Incidents data={data} open={setIncidentDetail} create={() => setModal({ kind: "incident" })} />}
    {tab === "impact" && <Impact data={data} edit={(item) => setModal({ kind: "assessment", item })} create={() => setModal({ kind: "assessment" })} configure={() => setModal({ kind: "settings" })} />}
    <footer className={styles.updated}>Atualizado em {dateTime.format(new Date(data.generatedAt))} · fuso {data.settings.timezone} · dados pessoais minimizados na interface</footer>
    {modal && <Editor modal={modal} data={data} busy={busy} close={() => setModal(null)} submit={submit} />}
    {requestDetail && <RequestDetail item={requestDetail} actors={data.actors} busy={busy} close={() => setRequestDetail(null)} command={async (payload) => { const result = await command(payload); if (result?.request) setRequestDetail(result.request as RequestItem); if (result) { setNotice("Solicitação atualizada com rastreabilidade."); await load(); } }} />}
    {incidentDetail && <IncidentDetail item={incidentDetail} actors={data.actors} busy={busy} close={() => setIncidentDetail(null)} command={async (payload) => { const result = await command(payload); if (result?.incident) setIncidentDetail(result.incident as Incident); if (result) { setNotice("Incidente atualizado com rastreabilidade."); await load(); } }} />}
  </div>;
}

function Overview({ data, maxTrend, openRequest, openIncident, configure, navigate }: { data: Data; maxTrend: number; openRequest: (item: RequestItem) => void; openIncident: (item: Incident) => void; configure: () => void; navigate: (tab: Tab) => void }) {
  const queue = data.requests.filter((item) => !["completed", "rejected"].includes(item.status)).sort((a, b) => urgency(b) - urgency(a)).slice(0, 6), incidents = data.incidents.filter((item) => item.status !== "resolved").slice(0, 5);
  return <section className={styles.overview}>
    <Panel eyebrow="OPERAÇÃO" title="Demanda e incidentes · 14 dias" action={<button type="button" onClick={() => navigate("requests")}>Abrir fila →</button>}><div className={styles.chart}>{data.trend.map((item) => <article key={item.date}><div><i style={{ height: `${item.requests / maxTrend * 100}%` }} /><i style={{ height: `${item.incidents / maxTrend * 100}%` }} /></div><small>{compact.format(new Date(`${item.date}T12:00:00`)).replace(" de ", " ")}</small></article>)}</div><div className={styles.legend}><span><i />Solicitações</span><span><i />Incidentes</span></div></Panel>
    <Panel eyebrow="FILA PRIORITÁRIA" title="Direitos dos titulares" action={<button type="button" onClick={() => navigate("requests")}>Ver todos →</button>}><div className={styles.queue}>{queue.map((item) => <button type="button" key={item.id} onClick={() => openRequest(item)}><Due value={item.dueAt} /><span><strong>{item.subjectName}</strong><small>{item.number} · {requestType(item.type)} · {requestStatus(item.status)}</small></span><b>›</b></button>)}{!queue.length && <Empty title="Fila controlada" text="Nenhuma solicitação aberta no momento." />}</div></Panel>
    <Panel eyebrow="PLANO DE CONFORMIDADE" title="Controles essenciais" action={<b className={styles.score}>{data.summary.readiness.score}%</b>}><div className={styles.checks}>{data.summary.readiness.checks.map((item) => <article className={item.ok ? styles.ok : styles.pending} key={item.key}><i>{item.ok ? "✓" : "!"}</i><span><strong>{item.label}</strong><small>{item.ok ? "Controle evidenciado" : "Ação recomendada"}</small></span></article>)}</div></Panel>
    <Panel eyebrow="RESPOSTA A INCIDENTES" title="Relógio regulatório" action={<button type="button" onClick={() => navigate("incidents")}>Central →</button>}><div className={styles.incidentQueue}>{incidents.map((item) => <button type="button" key={item.id} onClick={() => openIncident(item)}><Risk value={item.severity} /><span><strong>{item.title}</strong><small>{item.riskRelevant ? notificationClock(item) : "Relevância em avaliação"}</small></span><em>{incidentStatus(item.status)}</em></button>)}{!incidents.length && <Empty title="Nenhum incidente aberto" text="O histórico permanece disponível para prestação de contas." />}</div></Panel>
    <Panel eyebrow="ENCARREGADO" title="Canal de privacidade" action={<button type="button" onClick={configure}>Configurar →</button>}><div className={styles.dpo}><div><b>{initials(data.settings.dataProtectionOfficerName || "Não definido")}</b><span><strong>{data.settings.dataProtectionOfficerName || "Encarregado não definido"}</strong><small>{data.settings.dataProtectionEmail || "Informe o canal público de contato"}</small></span></div><dl><div><dt>Telefone</dt><dd>{data.settings.dataProtectionPhone || "Não informado"}</dd></div><div><dt>Prazo operacional</dt><dd>{data.settings.privacyDefaultRequestDays} dias</dd></div><div><dt>Próxima revisão</dt><dd>{data.settings.privacyProgramReviewAt ? date.format(new Date(data.settings.privacyProgramReviewAt)) : "Planejar"}</dd></div><div><dt>Enquadramento</dt><dd>{data.settings.privacySmallAgent ? "Pequeno porte · validar" : "Regra geral"}</dd></div></dl></div></Panel>
    <Panel eyebrow="TRANSPARÊNCIA" title="Manifestações registradas"><div className={styles.consent}><div><b>{data.summary.consentRecords.granted || 0}</b><span>Concedidas</span></div><div><b>{data.summary.consentRecords.revoked || 0}</b><span>Revogadas</span></div><div><b>{Object.values(data.summary.consentRecords).reduce((sum, value) => sum + value, 0)}</b><span>Total histórico</span></div><Link href="/erp/clientes">Gerenciar por titular →</Link></div></Panel>
  </section>;
}

function Requests({ data, filters, setFilters, apply, reset, page, setPage, open, create, exportCsv }: { data: Data; filters: Filters; setFilters: (value: Filters) => void; apply: (event: FormEvent) => void; reset: () => void; page: number; setPage: (value: number) => void; open: (item: RequestItem) => void; create: () => void; exportCsv: () => void }) {
  return <section className={styles.section}><header><div><span>DIREITOS DOS TITULARES</span><h2>Fila de solicitações</h2><p>Identidade, decisão, resposta e evidências com prazo e histórico por protocolo.</p></div><div><button type="button" onClick={() => void exportCsv()}>↓ Exportar CSV</button><button type="button" className={styles.primary} onClick={create}>＋ Nova solicitação</button></div></header>
    <form className={styles.filters} onSubmit={apply}><label className={styles.search}><span>Buscar</span><input value={filters.search} onChange={(event) => setFilters({ ...filters, search: event.target.value })} placeholder="Protocolo, titular ou responsável" /></label><label><span>Estado</span><select value={filters.status} onChange={(event) => setFilters({ ...filters, status: event.target.value })}><option value="">Todos</option>{["received","identity_pending","verified","in_progress","completed","rejected"].map((item) => <option value={item} key={item}>{requestStatus(item)}</option>)}</select></label><label><span>Direito</span><select value={filters.type} onChange={(event) => setFilters({ ...filters, type: event.target.value })}><option value="">Todos</option>{requestTypes().map((item) => <option value={item} key={item}>{requestType(item)}</option>)}</select></label><label><span>Prioridade</span><select value={filters.priority} onChange={(event) => setFilters({ ...filters, priority: event.target.value })}><option value="">Todas</option><option value="urgent">Urgente</option><option value="high">Alta</option><option value="normal">Normal</option></select></label><label><span>Ordenação</span><select value={filters.sort} onChange={(event) => setFilters({ ...filters, sort: event.target.value as Filters["sort"] })}><option value="newest">Mais recentes</option><option value="oldest">Mais antigas</option></select></label><button className={styles.primary}>Aplicar</button><button type="button" onClick={reset}>Limpar</button></form>
    <div className={styles.tableWrap}><table><thead><tr><th>Protocolo e titular</th><th>Direito</th><th>Etapa</th><th>Responsável</th><th>Prazo</th><th>Ações</th></tr></thead><tbody>{data.requests.map((item) => <tr key={item.id} className={daysUntil(item.dueAt) < 0 && !["completed","rejected"].includes(item.status) ? styles.overdue : ""}><td data-label="Protocolo"><button type="button" className={styles.entity} onClick={() => open(item)}><strong>{item.subjectName}</strong><small>{item.number} · {item.subjectDocument} · {item.contact}</small></button></td><td data-label="Direito">{requestType(item.type)}<small className={styles.muted}>{priorityLabel(item.priority)}</small></td><td data-label="Etapa"><Status value={item.status} /></td><td data-label="Responsável">{item.assignedTo || "A definir"}</td><td data-label="Prazo"><Due value={item.dueAt} closed={["completed","rejected"].includes(item.status)} /></td><td data-label="Ações"><details className={styles.menu}><summary aria-label={`Ações de ${item.number}`}>•••</summary><div><button type="button" onClick={() => open(item)}>Ver prontuário completo</button><button type="button" onClick={() => { navigator.clipboard?.writeText(item.number); }}>Copiar protocolo</button></div></details></td></tr>)}</tbody></table>{!data.requests.length && <Empty title="Nenhuma solicitação encontrada" text="Revise os filtros ou registre uma nova demanda do titular." />}</div>
    <Pagination page={page} pages={data.pagination.pages} total={data.pagination.total} setPage={setPage} />
  </section>;
}

function Inventory({ data, edit, create, createImpact }: { data: Data; edit: (item: Treatment) => void; create: () => void; createImpact: (item: Treatment) => void }) { return <section className={styles.section}><header><div><span>ROPA · ART. 37</span><h2>Inventário de tratamentos</h2><p>Finalidade, titulares, dados, operações, sistemas, compartilhamentos e riscos.</p></div><button type="button" className={styles.primary} onClick={create}>＋ Mapear tratamento</button></header><div className={styles.treatmentGrid}>{data.treatments.map((item) => <article className={styles.treatment} key={item.id}><header><Risk value={item.riskLevel} /><span><small>{item.department} · {basisLabel(item.legalBasis)}</small><h3>{item.name}</h3></span><Status value={item.status} /></header><p>{item.purpose}</p><div className={styles.tags}>{strings(item.dataCategories).slice(0,4).map((tag) => <span key={tag}>{tag}</span>)}{item.sensitiveData && <b>Dados sensíveis</b>}{item.childrenData && <b>Crianças/adolescentes</b>}{item.internationalTransfer && <b>Transferência internacional</b>}</div><dl><div><dt>Responsável</dt><dd>{item.owner}</dd></div><div><dt>Revisão</dt><dd>{item.nextReviewAt ? date.format(new Date(item.nextReviewAt)) : "Não planejada"}</dd></div><div><dt>RIPDs</dt><dd>{item._count.assessments}</dd></div></dl><footer><button type="button" onClick={() => edit(item)}>Editar inventário</button><button type="button" onClick={() => createImpact(item)}>Criar RIPD</button></footer></article>)}{!data.treatments.length && <Empty title="Inventário ainda vazio" text="Mapeie as operações para enxergar finalidade, base legal, retenção, compartilhamentos e risco." />}</div></section>; }

function Policies({ data, editBasis, editRetention, createBasis, createRetention }: { data: Data; editBasis: (item: LegalBasis) => void; editRetention: (item: Retention) => void; createBasis: () => void; createRetention: () => void }) { return <section className={styles.policyLayout}><section className={styles.section}><header><div><span>FINALIDADE E FUNDAMENTO</span><h2>Hipóteses legais</h2><p>Documentação por categoria, sistema, destinatário e revisão.</p></div><button type="button" className={styles.primary} onClick={createBasis}>＋ Nova base</button></header><div className={styles.policyList}>{data.bases.map((item) => <button type="button" key={item.id} onClick={() => editBasis(item)}><i className={item.active ? styles.activeDot : styles.offDot} /><span><strong>{item.name}</strong><small>{item.dataCategory} · {basisLabel(item.basis)}</small><p>{item.purpose}</p></span><b>›</b></button>)}{!data.bases.length && <Empty title="Sem bases mapeadas" text="Relacione finalidade, categoria e hipótese legal." />}</div></section><section className={styles.section}><header><div><span>CICLO DE VIDA</span><h2>Retenção e descarte</h2><p>Prazos documentados e destino final verificável.</p></div><button type="button" className={styles.primary} onClick={createRetention}>＋ Nova regra</button></header><div className={styles.policyList}>{data.retention.map((item) => <button type="button" key={item.id} onClick={() => editRetention(item)}><i className={item.active ? styles.activeDot : styles.offDot} /><span><strong>{item.dataCategory}</strong><small>{item.retentionDays.toLocaleString("pt-BR")} dias · {retentionLabel(item.action)}</small><p>{item.legalReason}</p></span><b>›</b></button>)}{!data.retention.length && <Empty title="Sem regras de retenção" text="Documente prazo, fundamento e destino por categoria." />}</div></section></section>; }

function Incidents({ data, open, create }: { data: Data; open: (item: Incident) => void; create: () => void }) { return <section className={styles.section}><header><div><span>RESOLUÇÃO CD/ANPD Nº 15/2024</span><h2>Resposta a incidentes</h2><p>Avaliação de relevância, contenção, comunicações e plano corretivo em histórico único.</p></div><button type="button" className={styles.primary} onClick={create}>＋ Registrar incidente</button></header><div className={styles.incidentGrid}>{data.incidents.map((item) => <button type="button" className={styles.incidentCard} key={item.id} onClick={() => open(item)}><header><Risk value={item.severity} /><span><small>{incidentStatus(item.status)}</small><strong>{item.title}</strong></span><b>›</b></header><p>{item.description}</p><dl><div><dt>Titulares</dt><dd>{item.affectedSubjects.toLocaleString("pt-BR")}</dd></div><div><dt>Relevância</dt><dd>{item.riskRelevant ? "Risco relevante" : "Não confirmada"}</dd></div><div><dt>Comunicação</dt><dd>{item.riskRelevant ? notificationClock(item) : "Avaliar"}</dd></div></dl><footer><span className={item.anpdNotifiedAt ? styles.done : ""}>ANPD {item.anpdNotifiedAt ? "✓" : "—"}</span><span className={item.subjectsNotifiedAt ? styles.done : ""}>Titulares {item.subjectsNotifiedAt ? "✓" : "—"}</span></footer></button>)}{!data.incidents.length && <Empty title="Nenhum incidente registrado" text="Use esta central para documentar inclusive avaliações que concluam pela não relevância." />}</div></section>; }

function Impact({ data, edit, create, configure }: { data: Data; edit: (item: Assessment) => void; create: () => void; configure: () => void }) { return <section className={styles.impactLayout}><section className={styles.section}><header><div><span>AVALIAÇÃO DE ALTO RISCO</span><h2>Relatórios de impacto</h2><p>Necessidade, proporcionalidade, riscos, salvaguardas e parecer do encarregado.</p></div><button type="button" className={styles.primary} onClick={create}>＋ Novo RIPD</button></header><div className={styles.assessments}>{data.assessments.map((item) => <button type="button" key={item.id} onClick={() => edit(item)}><header><Status value={item.status} /><Risk value={item.residualRisk} /></header><strong>{item.title}</strong><small>{item.treatment?.name || "Escopo independente"}</small><p>{item.reason}</p><footer><span>Risco inerente: {riskLabel(item.inherentRisk)}</span><span>Revisão: {item.reviewAt ? date.format(new Date(item.reviewAt)) : "não definida"}</span></footer></button>)}{!data.assessments.length && <Empty title="Nenhum RIPD elaborado" text="Comece pelos tratamentos de alto risco, dados sensíveis ou públicos vulneráveis." />}</div></section><aside className={styles.governance}><span>GOVERNANÇA CONTÍNUA</span><h2>Responsabilização demonstrável</h2><p>A prontidão não substitui avaliação jurídica. Ela evidencia os controles operacionais e destaca lacunas para decisão do controlador e do encarregado.</p><div>{data.summary.readiness.checks.map((item) => <span key={item.key}><i>{item.ok ? "✓" : "!"}</i>{item.label}</span>)}</div><button type="button" onClick={configure}>Configurar programa</button><Link href="/erp/atividades-auditoria">Abrir trilha de auditoria →</Link></aside></section>; }

function RequestDetail({ item, actors, busy, close, command }: { item: RequestItem; actors: Data["actors"]; busy: boolean; close: () => void; command: (payload: Record<string, unknown>) => Promise<void> }) { const next = requestNext(item.status), closed = ["completed","rejected"].includes(item.status); return <ErpModal close={close} className={styles.modalLayer} label={`Solicitação ${item.number}`}><section className={styles.detailDialog}><header><div><span>{item.number}</span><h2>{item.subjectName}</h2><p>{requestType(item.type)} · {item.subjectDocument} · {item.contact}</p></div><Due value={item.dueAt} closed={closed} /><button type="button" className={styles.close} onClick={close}>×</button></header><div className={styles.detailBody}><section className={styles.detailFacts}><div><small>Etapa</small><Status value={item.status} /></div><div><small>Prioridade</small><strong>{priorityLabel(item.priority)}</strong></div><div><small>Responsável</small><strong>{item.assignedTo || "A definir"}</strong></div><div><small>Versão</small><strong>v{item.version}</strong></div></section><section className={styles.detailColumns}><article><header><h3>Atendimento e evidências</h3></header><dl><div><dt>Canal</dt><dd>{channelLabel(item.channel)}</dd></div><div><dt>Solicitante</dt><dd>{relationLabel(item.requesterRelation)}</dd></div><div><dt>Identidade</dt><dd>{item.identityMethod || "Pendente"}</dd></div><div><dt>Evidência</dt><dd>{item.evidence || "Ainda não registrada"}</dd></div><div><dt>Resposta</dt><dd>{item.responseSummary || "Ainda não registrada"}</dd></div>{item.rejectionReason && <div><dt>Justificativa</dt><dd>{item.rejectionReason}</dd></div>}</dl></article><article><header><h3>Linha do tempo imutável</h3><b>{item.events?.length || 0}</b></header><div className={styles.timeline}>{item.events?.map((event) => <div key={event.id}><i /><span><strong>{eventLabel(event.kind, event.toStatus)}</strong><small>{event.actorName} · {dateTime.format(new Date(event.createdAt))}</small>{event.note && <p>{event.note}</p>}</span></div>)}{!item.events?.length && <p>O histórico aparecerá após a próxima atualização.</p>}</div></article></section>{next.length > 0 && <form className={styles.actionForm} onSubmit={(event) => { event.preventDefault(); void command({ action: "request.transition", requestId: item.id, expectedVersion: item.version, ...formValues(event.currentTarget) }); }}><header><div><h3>Avançar atendimento</h3><p>A etapa é registrada na linha do tempo e na auditoria geral.</p></div></header><div><Field label="Próxima etapa"><select name="status" required>{next.map((status) => <option value={status} key={status}>{requestStatus(status)}</option>)}</select></Field><Field label="Responsável"><select name="assignedTo" defaultValue={item.assignedTo || ""}><option value="">Manter responsável</option>{actors.map((actor) => <option value={actor.name} key={actor.id}>{actor.name}</option>)}</select></Field><Field label="Método de validação"><input name="identityMethod" defaultValue={item.identityMethod || ""} placeholder="Documento + confirmação no canal cadastrado" /></Field><Field label="Referência da evidência"><input name="evidence" defaultValue={item.evidence || ""} placeholder="Arquivo, protocolo ou hash — não cole dados pessoais" /></Field><Field label="Resumo da resposta" wide><textarea name="responseSummary" defaultValue={item.responseSummary || ""} placeholder="Resultado comunicado ao titular" /></Field><Field label="Justificativa do não atendimento" wide><textarea name="rejectionReason" defaultValue={item.rejectionReason || ""} /></Field><Field label="Anotação desta etapa" wide><textarea name="note" /></Field></div><footer><button type="submit" className={styles.primary} disabled={busy}>Registrar etapa</button></footer></form>}<form className={styles.noteForm} onSubmit={(event) => { event.preventDefault(); const values = formValues(event.currentTarget); void command({ action: "request.note", requestId: item.id, ...values }); event.currentTarget.reset(); }}><Field label="Nova anotação"><textarea name="note" minLength={2} required placeholder="Contexto operacional sem reproduzir dados pessoais desnecessários" /></Field><button type="submit" disabled={busy}>Adicionar ao histórico</button></form></div></section></ErpModal>; }

function IncidentDetail({ item, actors, busy, close, command }: { item: Incident; actors: Data["actors"]; busy: boolean; close: () => void; command: (payload: Record<string, unknown>) => Promise<void> }) { const next = incidentNext(item.status); return <ErpModal close={close} className={styles.modalLayer} label={`Incidente ${item.title}`}><section className={styles.detailDialog}><header><div><span>INCIDENTE · {riskLabel(item.severity)}</span><h2>{item.title}</h2><p>{item.riskRelevant ? notificationClock(item) : "Relevância ainda não confirmada"}</p></div><Status value={item.status} /><button type="button" className={styles.close} onClick={close}>×</button></header><div className={styles.detailBody}><section className={styles.incidentFacts}><div><small>Detectado</small><strong>{dateTime.format(new Date(item.detectedAt))}</strong></div><div><small>Titulares afetados</small><strong>{item.affectedSubjects.toLocaleString("pt-BR")}</strong></div><div><small>ANPD</small><strong>{item.anpdNotifiedAt ? dateTime.format(new Date(item.anpdNotifiedAt)) : "Não registrada"}</strong></div><div><small>Titulares</small><strong>{item.subjectsNotifiedAt ? dateTime.format(new Date(item.subjectsNotifiedAt)) : "Não registrada"}</strong></div></section><section className={styles.detailColumns}><article><header><h3>Avaliação e resposta</h3></header><p>{item.description}</p><dl><div><dt>Categorias</dt><dd>{strings(item.dataCategories).join(", ")}</dd></div><div><dt>Decisão de relevância</dt><dd>{item.decisionReason || "Em avaliação"}</dd></div><div><dt>Contenção</dt><dd>{item.containmentMeasures || "Pendente"}</dd></div><div><dt>Causa raiz</dt><dd>{item.rootCause || "Pendente"}</dd></div><div><dt>Ações corretivas</dt><dd>{item.correctiveActions || "Pendente"}</dd></div></dl></article><article><header><h3>Linha do tempo imutável</h3><b>{item.events.length}</b></header><div className={styles.timeline}>{item.events.map((event) => <div key={event.id}><i /><span><strong>{eventLabel(event.kind, event.toStatus)}</strong><small>{event.actorName} · {dateTime.format(new Date(event.createdAt))}</small>{event.note && <p>{event.note}</p>}</span></div>)}</div></article></section>{next.length > 0 && <form className={styles.actionForm} onSubmit={(event) => { event.preventDefault(); void command({ action: "incident.transition", incidentId: item.id, expectedVersion: item.version, ...formValues(event.currentTarget) }); }}><header><div><h3>Atualizar resposta</h3><p>Incidentes relevantes só podem ser encerrados após registrar ambas as comunicações.</p></div></header><div><Field label="Etapa"><select name="status">{[item.status, ...next].map((status) => <option value={status} key={status}>{incidentStatus(status)}</option>)}</select></Field><Field label="Responsável"><select name="assignedTo" defaultValue={item.assignedTo || ""}><option value="">Manter responsável</option>{actors.map((actor) => <option key={actor.id}>{actor.name}</option>)}</select></Field><label className={styles.check}><input type="checkbox" name="riskRelevant" defaultChecked={item.riskRelevant} /><span>Risco ou dano relevante confirmado</span></label><label className={styles.check}><input type="checkbox" name="markAnpdNotified" defaultChecked={Boolean(item.anpdNotifiedAt)} disabled={Boolean(item.anpdNotifiedAt)} /><span>Comunicação à ANPD realizada</span></label><label className={styles.check}><input type="checkbox" name="markSubjectsNotified" defaultChecked={Boolean(item.subjectsNotifiedAt)} disabled={Boolean(item.subjectsNotifiedAt)} /><span>Comunicação aos titulares realizada</span></label><Field label="Justificativa da relevância" wide><textarea name="decisionReason" defaultValue={item.decisionReason || ""} /></Field><Field label="Medidas de contenção" wide><textarea name="containmentMeasures" defaultValue={item.containmentMeasures || ""} /></Field><Field label="Causa raiz" wide><textarea name="rootCause" defaultValue={item.rootCause || ""} /></Field><Field label="Ações corretivas" wide><textarea name="correctiveActions" defaultValue={item.correctiveActions || ""} /></Field><Field label="Anotação da etapa" wide><textarea name="note" /></Field></div><footer><button className={styles.primary} disabled={busy}>Registrar atualização</button></footer></form>}</div></section></ErpModal>; }

function Editor({ modal, data, busy, close, submit }: { modal: Modal; data: Data; busy: boolean; close: () => void; submit: (action: string, payload: Record<string, unknown>) => Promise<void> }) { const item = modal.item; function save(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const action = ({ request: "request.create", basis: "basis.save", retention: "retention.save", incident: "incident.create", treatment: "treatment.save", assessment: "assessment.save", settings: "settings.save" } as const)[modal.kind]; void submit(action, formValues(event.currentTarget)); } return <ErpModal close={close} className={styles.modalLayer} label={editorTitle(modal.kind)}><form className={styles.editor} onSubmit={save}><header><div><span>PRIVACIDADE E LGPD</span><h2>{editorTitle(modal.kind)}</h2><p>{editorSubtitle(modal.kind)}</p></div><button type="button" onClick={close}>×</button></header><div>{modal.kind === "request" && <RequestFields actors={data.actors} />}{modal.kind === "basis" && <BasisFields item={item as LegalBasis | undefined} />}{modal.kind === "retention" && <RetentionFields item={item as Retention | undefined} />}{modal.kind === "incident" && <IncidentFields actors={data.actors} />}{modal.kind === "treatment" && <TreatmentFields item={item as Treatment | undefined} />}{modal.kind === "assessment" && <AssessmentFields item={item as Assessment | undefined} treatments={data.treatments} />}{modal.kind === "settings" && <SettingsFields settings={data.settings} />}</div><footer><button type="button" onClick={close}>Cancelar</button><button className={styles.primary} disabled={busy}>{busy ? "Registrando…" : "Salvar com auditoria"}</button></footer></form></ErpModal>; }

function RequestFields({ actors }: { actors: Data["actors"] }) { return <><Field label="Direito do titular"><select name="type">{requestTypes().map((item) => <option value={item} key={item}>{requestType(item)}</option>)}</select></Field><Field label="Prioridade"><select name="priority"><option value="normal">Normal</option><option value="high">Alta</option><option value="urgent">Urgente</option></select></Field><Field label="Nome do titular" wide><input name="subjectName" required /></Field><Field label="CPF ou CNPJ"><input name="subjectDocument" inputMode="numeric" required /></Field><Field label="Contato"><input name="contact" required /></Field><Field label="Canal"><select name="channel"><option value="email">E-mail</option><option value="phone">Telefone</option><option value="portal">Portal</option><option value="in_person">Presencial</option><option value="letter">Carta</option></select></Field><Field label="Solicitante"><select name="requesterRelation"><option value="self">Próprio titular</option><option value="legal_representative">Representante legal</option><option value="guardian">Responsável/guardião</option></select></Field><Field label="Responsável"><select name="assignedTo"><option value="">Usuário atual</option>{actors.map((actor) => <option value={actor.name} key={actor.id}>{actor.name}</option>)}</select></Field><Field label="Contexto inicial" wide><textarea name="note" placeholder="Registre o pedido sem copiar dados pessoais desnecessários" /></Field><div className={styles.formHint}><b>Proteção no armazenamento</b><span>Documento e contato serão criptografados. A interface exibe somente versões mascaradas.</span></div></>; }
function BasisFields({ item }: { item?: LegalBasis }) { return <><input type="hidden" name="basisId" value={item?.id || ""} /><input type="hidden" name="expectedVersion" value={item?.version || ""} /><Field label="Nome"><input name="name" defaultValue={item?.name} required /></Field><Field label="Hipótese legal"><BasisSelect defaultValue={item?.basis} /></Field><Field label="Categoria de dados"><input name="dataCategory" defaultValue={item?.dataCategory} required /></Field><Field label="Responsável"><input name="owner" defaultValue={item?.owner || ""} /></Field><Field label="Finalidade" wide><textarea name="purpose" defaultValue={item?.purpose} required /></Field><Field label="Descrição" wide><textarea name="description" defaultValue={item?.description || ""} /></Field><Field label="Categorias de titulares"><input name="dataSubjects" defaultValue={strings(item?.dataSubjects).join(", ")} /></Field><Field label="Sistemas de origem"><input name="sourceSystems" defaultValue={strings(item?.sourceSystems).join(", ")} /></Field><Field label="Destinatários"><input name="recipients" defaultValue={strings(item?.recipients).join(", ")} /></Field><Field label="Revisão"><input type="date" name="reviewAt" defaultValue={isoDate(item?.reviewAt)} /></Field><label className={styles.check}><input type="checkbox" name="internationalTransfer" defaultChecked={item?.internationalTransfer} /><span>Há transferência internacional</span></label><label className={styles.check}><input type="checkbox" name="active" defaultChecked={item?.active ?? true} /><span>Mapeamento ativo</span></label><Field label="Salvaguardas" wide><textarea name="safeguards" defaultValue={item?.safeguards || ""} /></Field></>; }
function RetentionFields({ item }: { item?: Retention }) { return <><input type="hidden" name="ruleId" value={item?.id || ""} /><input type="hidden" name="expectedVersion" value={item?.version || ""} /><Field label="Categoria de dados"><input name="dataCategory" defaultValue={item?.dataCategory} required /></Field><Field label="Prazo em dias"><input type="number" min="1" max="36500" name="retentionDays" defaultValue={item?.retentionDays || 365} required /></Field><Field label="Destino final"><select name="retentionAction" defaultValue={item?.action || "anonymize"}><option value="anonymize">Anonimizar</option><option value="delete">Eliminar</option><option value="review">Revisar manualmente</option></select></Field><Field label="Responsável"><input name="owner" defaultValue={item?.owner || ""} /></Field><Field label="Fundamento" wide><textarea name="legalReason" defaultValue={item?.legalReason} required /></Field><Field label="Escopo de aplicação" wide><textarea name="appliesTo" defaultValue={item?.appliesTo || ""} /></Field><Field label="Revisão"><input type="date" name="reviewAt" defaultValue={isoDate(item?.reviewAt)} /></Field><label className={styles.check}><input type="checkbox" name="active" defaultChecked={item?.active ?? true} /><span>Regra ativa</span></label></>; }
function TreatmentFields({ item }: { item?: Treatment }) { return <><input type="hidden" name="treatmentId" value={item?.id || ""} /><input type="hidden" name="expectedVersion" value={item?.version || ""} /><Field label="Operação de tratamento" wide><input name="name" defaultValue={item?.name} required /></Field><Field label="Área responsável"><input name="department" defaultValue={item?.department} required /></Field><Field label="Dono do processo"><input name="owner" defaultValue={item?.owner} required /></Field><Field label="Hipótese legal"><BasisSelect defaultValue={item?.legalBasis} /></Field><Field label="Nível de risco"><RiskSelect name="riskLevel" defaultValue={item?.riskLevel} /></Field><Field label="Estado"><select name="status" defaultValue={item?.status || "active"}><option value="draft">Rascunho</option><option value="active">Ativo</option><option value="review_due">Revisão vencida</option><option value="archived">Arquivado</option></select></Field><Field label="Próxima revisão"><input type="date" name="nextReviewAt" defaultValue={isoDate(item?.nextReviewAt)} /></Field><Field label="Finalidade" wide><textarea name="purpose" defaultValue={item?.purpose} required /></Field><Field label="Categorias de dados"><input name="dataCategories" defaultValue={strings(item?.dataCategories).join(", ")} required /></Field><Field label="Categorias de titulares"><input name="dataSubjects" defaultValue={strings(item?.dataSubjects).join(", ")} required /></Field><Field label="Operações realizadas"><input name="operations" defaultValue={strings(item?.operations).join(", ")} placeholder="coleta, uso, armazenamento, compartilhamento" required /></Field><Field label="Sistemas"><input name="systems" defaultValue={strings(item?.systems).join(", ")} /></Field><Field label="Fonte de coleta"><input name="collectionSource" defaultValue={item?.collectionSource || ""} /></Field><Field label="Destinatários"><input name="recipients" defaultValue={strings(item?.recipients).join(", ")} /></Field><Field label="Retenção" wide><textarea name="retentionSummary" defaultValue={item?.retentionSummary || ""} /></Field><Field label="Medidas de segurança" wide><textarea name="securityMeasures" defaultValue={item?.securityMeasures || ""} /></Field><label className={styles.check}><input type="checkbox" name="sensitiveData" defaultChecked={item?.sensitiveData} /><span>Envolve dados sensíveis</span></label><label className={styles.check}><input type="checkbox" name="childrenData" defaultChecked={item?.childrenData} /><span>Envolve crianças/adolescentes</span></label><label className={styles.check}><input type="checkbox" name="internationalTransfer" defaultChecked={item?.internationalTransfer} /><span>Transferência internacional</span></label><Field label="Salvaguardas de transferência" wide><textarea name="transferSafeguards" defaultValue={item?.transferSafeguards || ""} /></Field></>; }
function AssessmentFields({ item, treatments }: { item?: Assessment; treatments: Treatment[] }) { return <><input type="hidden" name="assessmentId" value={item?.id || ""} /><input type="hidden" name="expectedVersion" value={item?.version || ""} /><Field label="Título" wide><input name="title" defaultValue={item?.title} required /></Field><Field label="Tratamento relacionado"><select name="treatmentId" defaultValue={item?.treatmentId || ""}><option value="">Escopo independente</option>{treatments.map((treatment) => <option value={treatment.id} key={treatment.id}>{treatment.name}</option>)}</select></Field><Field label="Estado"><select name="status" defaultValue={item?.status || "draft"}><option value="draft">Rascunho</option><option value="in_review">Em revisão</option><option value="approved">Aprovado</option><option value="superseded">Substituído</option></select></Field><Field label="Risco inerente"><RiskSelect name="inherentRisk" defaultValue={item?.inherentRisk || "high"} /></Field><Field label="Risco residual"><RiskSelect name="residualRisk" defaultValue={item?.residualRisk || "medium"} /></Field><Field label="Revisão"><input type="date" name="reviewAt" defaultValue={isoDate(item?.reviewAt)} /></Field><Field label="Justificativa" wide><textarea name="reason" defaultValue={item?.reason} required /></Field><Field label="Riscos identificados" wide><textarea name="risks" defaultValue={strings(item?.risks).join("\n")} required /></Field><Field label="Salvaguardas e mitigações" wide><textarea name="safeguards" defaultValue={strings(item?.safeguards).join("\n")} required /></Field><Field label="Necessidade" wide><textarea name="necessity" defaultValue={item?.necessity || ""} /></Field><Field label="Proporcionalidade" wide><textarea name="proportionality" defaultValue={item?.proportionality || ""} /></Field><Field label="Parecer do encarregado" wide><textarea name="dpoOpinion" defaultValue={item?.dpoOpinion || ""} /></Field></>; }
function IncidentFields({ actors }: { actors: Data["actors"] }) { return <><Field label="Título" wide><input name="title" required /></Field><Field label="Severidade"><RiskSelect name="severity" defaultValue="medium" /></Field><Field label="Titulares afetados"><input type="number" min="0" name="affectedSubjects" defaultValue="0" /></Field><Field label="Detectado em"><input type="datetime-local" name="detectedAt" defaultValue={new Date().toISOString().slice(0,16)} required /></Field><Field label="Responsável"><select name="assignedTo"><option value="">Usuário atual</option>{actors.map((actor) => <option value={actor.name} key={actor.id}>{actor.name}</option>)}</select></Field><Field label="Descrição" wide><textarea name="description" minLength={10} required /></Field><Field label="Categorias de dados" wide><input name="dataCategories" placeholder="identificação, financeiro, credenciais" required /></Field><label className={styles.check}><input type="checkbox" name="riskRelevant" /><span>Pode causar risco ou dano relevante</span></label><Field label="Justificativa da avaliação" wide><textarea name="decisionReason" placeholder="Obrigatória quando a avaliação concluir pela não relevância" /></Field></>; }
function SettingsFields({ settings }: { settings: Data["settings"] }) { return <><Field label="Nome do encarregado"><input name="dataProtectionOfficerName" defaultValue={settings.dataProtectionOfficerName || ""} /></Field><Field label="E-mail público"><input type="email" name="dataProtectionEmail" defaultValue={settings.dataProtectionEmail || ""} /></Field><Field label="Telefone"><input name="dataProtectionPhone" defaultValue={settings.dataProtectionPhone || ""} /></Field><Field label="Prazo operacional padrão"><input type="number" min="1" max="60" name="privacyDefaultRequestDays" defaultValue={settings.privacyDefaultRequestDays} /></Field><Field label="Próxima revisão do programa"><input type="date" name="privacyProgramReviewAt" defaultValue={isoDate(settings.privacyProgramReviewAt)} /></Field><label className={styles.check}><input type="checkbox" name="privacySmallAgent" defaultChecked={settings.privacySmallAgent} /><span>Organização avaliada como agente de pequeno porte</span></label><div className={styles.formHint}><b>Validação necessária</b><span>O enquadramento e eventuais prazos diferenciados dependem dos requisitos legais aplicáveis à organização.</span></div></>; }

function Panel({ eyebrow, title, action, children }: { eyebrow: string; title: string; action?: ReactNode; children: ReactNode }) { return <section className={styles.panel}><header><div><span>{eyebrow}</span><h2>{title}</h2></div>{action}</header>{children}</section>; }
function Metric({ label, value, detail, tone = "neutral" }: { label: string; value: number; detail: string; tone?: "neutral" | "good" | "warning" | "danger" }) { return <article className={`${styles.metric} ${styles[`metric_${tone}`]}`}><span>{label}</span><strong>{value.toLocaleString("pt-BR")}</strong><small>{detail}</small></article>; }
function Field({ label, wide, children }: { label: string; wide?: boolean; children: ReactNode }) { return <label className={wide ? styles.wide : ""}><span>{label}</span>{children}</label>; }
function Status({ value }: { value: string }) { return <span className={`${styles.status} ${styles[`status_${value}`] || ""}`}>{statusAny(value)}</span>; }
function Risk({ value }: { value: string }) { return <span className={`${styles.risk} ${styles[`risk_${value}`]}`}>{riskLabel(value)}</span>; }
function Due({ value, closed = false }: { value: string; closed?: boolean }) { const days = daysUntil(value); return <span className={`${styles.due} ${!closed && days < 0 ? styles.dueLate : !closed && days <= 3 ? styles.dueSoon : ""}`}><b>{date.format(new Date(value))}</b><small>{closed ? "prazo encerrado" : days < 0 ? `${Math.abs(days)}d vencida` : days === 0 ? "vence hoje" : `${days}d restantes`}</small></span>; }
function Pagination({ page, pages, total, setPage }: { page: number; pages: number; total: number; setPage: (page: number) => void }) { return <footer className={styles.pagination}><span>{total.toLocaleString("pt-BR")} solicitações · página {page} de {pages}</span><div><button type="button" disabled={page <= 1} onClick={() => setPage(page - 1)}>← Anterior</button><button type="button" disabled={page >= pages} onClick={() => setPage(page + 1)}>Próxima →</button></div></footer>; }
function Empty({ title, text }: { title: string; text: string }) { return <div className={styles.empty}><b>◇</b><strong>{title}</strong><p>{text}</p></div>; }
function Loading() { return <div className={styles.loading} aria-label="Carregando central de privacidade"><div /><div /><div /><div /><section /></div>; }
function Fatal({ message, retry }: { message: string; retry: () => void }) { return <section className={styles.fatal}><ErpIcon name="privacy" /><h2>Não foi possível abrir a central</h2><p>{message}</p><button type="button" onClick={retry}>Tentar novamente</button></section>; }
function BasisSelect({ defaultValue }: { defaultValue?: string }) { return <select name="basis" defaultValue={defaultValue || "consent"}>{["consent","contract","legal_obligation","legitimate_interest","credit_protection","public_policy","research","health","legal_claims","fraud_prevention","life_protection"].map((item) => <option value={item} key={item}>{basisLabel(item)}</option>)}</select>; }
function RiskSelect({ name, defaultValue }: { name: string; defaultValue?: string }) { return <select name={name} defaultValue={defaultValue || "medium"}><option value="low">Baixo</option><option value="medium">Médio</option><option value="high">Alto</option><option value="critical">Crítico</option></select>; }

function formValues(form: HTMLFormElement) { const values: Record<string, unknown> = Object.fromEntries(new FormData(form)); for (const input of form.querySelectorAll<HTMLInputElement>('input[type="checkbox"]')) values[input.name] = input.checked; return values; }
function filterParams(filters: Filters) { const params = new URLSearchParams(); for (const [key, value] of Object.entries(filters)) if (value) params.set(key, value); return params; }
function strings(value: unknown) { return Array.isArray(value) ? value.filter((item): item is string => typeof item === "string") : []; }
function daysUntil(value: string) { const target = new Date(value); target.setHours(23,59,59,999); return Math.ceil((target.valueOf() - Date.now()) / 86_400_000); }
function urgency(item: RequestItem) { return (item.priority === "urgent" ? 1000 : item.priority === "high" ? 500 : 0) - daysUntil(item.dueAt); }
function notificationClock(item: Incident) { if (!item.notificationDueAt) return "Prazo não calculado"; if (item.anpdNotifiedAt && item.subjectsNotifiedAt) return "Comunicações registradas"; const hours = Math.ceil((new Date(item.notificationDueAt).valueOf() - Date.now()) / 3_600_000); return hours < 0 ? `${Math.abs(hours)}h além do prazo` : `${hours}h para comunicar`; }
function isoDate(value: string | null | undefined) { return value ? new Date(value).toISOString().slice(0,10) : ""; }
function initials(value: string) { return value.split(/\s+/).slice(0,2).map((part) => part[0]).join("").toUpperCase(); }
function requestTypes() { return ["access","correction","deletion","portability","revocation","restriction","objection","anonymization","info_sharing"]; }
function requestNext(value: string) { return ({ received: ["identity_pending","verified","rejected"], identity_pending: ["verified","rejected"], verified: ["in_progress","completed","rejected"], in_progress: ["completed","rejected"] } as Record<string,string[]>)[value] || []; }
function incidentNext(value: string) { return ({ open: ["assessing","contained","resolved"], assessing: ["contained","notifying","resolved"], contained: ["notifying","resolved"], notifying: ["resolved"] } as Record<string,string[]>)[value] || []; }
function requestType(value: string) { return ({ access: "Acesso e confirmação", correction: "Correção", deletion: "Eliminação", portability: "Portabilidade", revocation: "Revogação", restriction: "Restrição", objection: "Oposição", anonymization: "Anonimização", info_sharing: "Informações de compartilhamento" } as Record<string,string>)[value] || value; }
function requestStatus(value: string) { return ({ received: "Recebida", identity_pending: "Identidade pendente", verified: "Identidade validada", in_progress: "Em atendimento", completed: "Concluída", rejected: "Não atendida" } as Record<string,string>)[value] || value; }
function incidentStatus(value: string) { return ({ open: "Aberto", assessing: "Em avaliação", contained: "Contido", notifying: "Em comunicação", resolved: "Resolvido" } as Record<string,string>)[value] || value; }
function statusAny(value: string) { return ({ draft: "Rascunho", active: "Ativo", review_due: "Revisão vencida", archived: "Arquivado", in_review: "Em revisão", approved: "Aprovado", superseded: "Substituído", ...Object.fromEntries(["received","identity_pending","verified","in_progress","completed","rejected"].map((item) => [item, requestStatus(item)])), open: "Aberto", assessing: "Em avaliação", contained: "Contido", notifying: "Em comunicação", resolved: "Resolvido" } as Record<string,string>)[value] || value; }
function riskLabel(value: string) { return ({ low: "Baixo", medium: "Médio", high: "Alto", critical: "Crítico" } as Record<string,string>)[value] || value; }
function priorityLabel(value: string) { return ({ normal: "Prioridade normal", high: "Prioridade alta", urgent: "Urgente" } as Record<string,string>)[value] || value; }
function basisLabel(value: string) { return ({ consent: "Consentimento", contract: "Execução de contrato", legal_obligation: "Obrigação legal/regulatória", legitimate_interest: "Legítimo interesse", credit_protection: "Proteção do crédito", public_policy: "Política pública", research: "Estudos por órgão de pesquisa", health: "Tutela da saúde", legal_claims: "Exercício de direitos", fraud_prevention: "Prevenção à fraude", life_protection: "Proteção da vida" } as Record<string,string>)[value] || value; }
function retentionLabel(value: string) { return ({ anonymize: "anonimizar", delete: "eliminar", review: "revisar" } as Record<string,string>)[value] || value; }
function relationLabel(value: string) { return ({ self: "Próprio titular", legal_representative: "Representante legal", guardian: "Responsável/guardião" } as Record<string,string>)[value] || value; }
function channelLabel(value: string) { return ({ email: "E-mail", phone: "Telefone", portal: "Portal", in_person: "Presencial", letter: "Carta" } as Record<string,string>)[value] || value; }
function eventLabel(kind: string, status: string | null) { return kind === "created" ? "Registro recebido" : kind === "note" ? "Anotação adicionada" : kind === "migration" ? "Histórico inicial" : status ? `Etapa: ${statusAny(status)}` : kind; }
function editorTitle(kind: Modal["kind"]) { return ({ request: "Nova solicitação do titular", basis: "Mapeamento de hipótese legal", retention: "Regra de retenção e descarte", incident: "Registro de incidente", treatment: "Operação de tratamento", assessment: "Relatório de impacto — RIPD", settings: "Programa e encarregado" } as Record<Modal["kind"],string>)[kind]; }
function editorSubtitle(kind: Modal["kind"]) { return ({ request: "A identificação será criptografada e o prazo calculado automaticamente.", basis: "Documente finalidade, titulares, sistemas, compartilhamentos e revisão.", retention: "Associe prazo, fundamento, escopo e destino final.", incident: "Registre fatos, impacto inicial e decisão de relevância.", treatment: "Complete o inventário para sustentar transparência e avaliação de risco.", assessment: "Documente necessidade, proporcionalidade, riscos e salvaguardas.", settings: "Mantenha o canal do encarregado e o ciclo de revisão do programa." } as Record<Modal["kind"],string>)[kind]; }
